def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings."""
    # Simple implementation to find first differing position
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # Strings are identical up to min length
        if len(s_in) == len(s_out):
            return None  # No difference
        else:
            # One string is longer
            pos = min_len

    # Get the substring that needs to change
    if pos >= len(s_in):
        old_sub = ""
        new_sub = s_out[pos:]
    elif pos >= len(s_out):
        old_sub = s_in[pos:]
        new_sub = ""
    else:
        # Find the longest matching prefix/suffix to determine context
        old_sub = s_in[pos:min(pos+3, len(s_in))]
        new_sub = s_out[pos:min(pos+3, len(s_out))]

    return (old_sub, new_sub, pos)

def propose_rule_candidates(s_in, s_out):
    """Generate candidate replacement rules from a change."""
    # This is a simplified version - in reality this would be more complex
    edits = find_minimal_edit(s_in, s_out)
    if edits is None:
        return []

    old_sub, new_sub, pos = edits

    # Generate candidates from most specific to general
    candidates = []

    # Specific pattern: exact match of the changed portion
    if pos < len(s_in) and pos < len(s_out):
        candidates.append((old_sub, new_sub))

    # General patterns - we'll include some basic ones
    if len(old_sub) > 1:
        candidates.append((old_sub[:1], new_sub[:1]))  # First char only
        candidates.append((old_sub[-1:], new_sub[-1:]))  # Last char only

    # Add a general case
    if old_sub != new_sub:
        candidates.append((old_sub, new_sub))

    return candidates

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules match the input/output pairs."""
    result = apply_rules(inputs, rules)
    correct = sum(1 for i, o in zip(result, outputs) if i == o)
    return correct / len(outputs)

def find_over_applications(inputs, outputs, rules):
    """Find if any rules over-apply to unchanged pairs."""
    result = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, res) in enumerate(zip(inputs, outputs, result)):
        if inp != outp and inp == res:
            # Rule applied to something that shouldn't change
            over_apps.append((i, inp, res))
        elif inp != outp and res != outp:
            # Rule didn't produce correct output
            over_apps.append((i, inp, res))
    return over_apps

def simulate_rule_chain(s, rules):
    """Simulate applying rules step by step."""
    trace = []
    current = s
    for pattern, replacement in rules:
        prev = current
        current = current.replace(pattern, replacement)
        trace.append({
            'pattern': pattern,
            'replacement': replacement,
            'before': prev,
            'after': current
        })
    return trace

def build_proxy_rules(pattern, replacement, proxy="__X__"):
    """Build proxy rules to prevent counterfeeding."""
    pre_rule = (pattern, proxy)
    post_rule = (proxy, replacement)
    return (pre_rule, post_rule)

